 Result advanceBefore(ControllerDeviceState&d,ControllerInterruptRuntime&irq,ControllerDspTransferRuntime&dsp,unsigned budget){if(bound_!=&d||!irq.boundTo(d)||!dsp.boundTo(d))return {0,false,Block::NotBound};if(!active())return {0,false,Block::Inactive};if(d.interruptMode2||d.pendingIrqsHigh)return {0,false,Block::UnsupportedMode};if(irq.active()||(d.pendingIrqs&&irq.mask()==ControllerInterruptRuntime::Mask::Enabled))return {0,false,Block::NeedsInterrupt};if(dsp.active()&&!ownsDsp_)return {0,false,Block::DspBusy};if(ownsDsp_){auto r=dsp.advanceBefore(d,irq,budget);if(r.returned){ownsDsp_=false;word_->resumeDsp();}return {r.clocks,false,Block::None};}auto c=word_?word_->nextClocks():root_?rootCost():cost(d.lastWrite),arb=d.pendingIrqs?1u:0u;if(!c||budget<c+arb)return {};if(arb)(void)d.read8(0xfffff2);auto begin=d.cycles;auto history=[](uint32_t a){a&=0xffffff;return a<0x400000||(a>=0xfffd10&&a<0xffffa0)?int(a):-1;};auto read=[&](uint32_t a,unsigned n,unsigned end){uint32_t v=0;unsigned total=n==4?6:3;for(unsigned i=0;i<n;++i){d.cycles=begin+end-total+(n==4&&i<2?3:total);d.lastRead=history(a+i);v=(v<<8)|d.readResource(a+i);}return v;};auto write=[&](uint32_t a,uint16_t v,unsigned end){for(unsigned i=0;i<2;++i){d.cycles=begin+end;d.lastWrite=history(a+i);d.writeResource(a+i,uint8_t(v>>(8*(1-i))));}};bool stack=false;
 if(word_){stack=word_->stackWrites();word_->advanceBefore(c,read);if(word_->awaitingDsp()){if(!dsp.startWrite(word_->address(),word_->word()))return {};ownsDsp_=true;}else if(word_->complete()){word_.reset();task_->resume(T::Child::Send,0);}}
 else if(root_){stack=root_->stage()==RS::Save;root_->advance([](uint32_t){return 0u;});if(root_->complete()){auto value=root_->result();root_.reset();task_->resume(T::Child::Root,value);}}
 else{auto stage=task_->stage();stack=stage==S::SaveShape||stage==S::Root||stage==S::SendShape||stage==S::SendGain||stage==S::SendResult;task_->advance([&](T::Read f,uint32_t a){return read(a,f==T::Read::Table?2:1,stage==S::ReadTable?c-2:c);},[&](uint32_t a,uint16_t v){write(a,v,c);});if(task_->awaitingChild()){if(task_->child()==T::Child::Root)root_.emplace(task_->rootInput());else{result_=task_->value();auto command=stage==S::SendShape?0x3d0:stage==S::SendGain?0x3d1:0x3d2;word_.emplace(uint16_t(command),(result_>>8)&0xffffff);}}}
 d.cycles=begin+c;d.lastRead=-1;if(stack)d.lastWrite=-1;bool done=task_->complete();if(done)task_.reset();return {c+arb,done,Block::None};}
